excels.excel:

EXPORT WITH SHEET="生产设备OEE分析表", HEADER=true,
    MAPPING={"a":"设备编号","b":"设备名称","c":"时间开动率","d":"性能开动率","e":"合格品率","f":"OEE","g":"评价"},
    FORMAT={"c":"0.00%","d":"0.00%","e":"0.00%","f":"0.00%"},
    FORMULAS={
        F2:'C2*D2*E2',F3:'C3*D3*E3',F4:'C4*D4*E4',F5:'C5*D5*E5',F6:'C6*D6*E6',
        F7:'AVERAGE(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
